CREATE TABLE `ts_physical_alerts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `last_state_change_at` datetime(6) NOT NULL,
  `repository_id` bigint unsigned NOT NULL,
  `logical_alert_id` bigint unsigned DEFAULT NULL,
  `rule_id` bigint unsigned NOT NULL,
  `fingerprint` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `file_path` varchar(4096) COLLATE utf8mb4_general_ci NOT NULL,
  `start_line` int unsigned DEFAULT NULL,
  `end_line` int unsigned DEFAULT NULL,
  `start_column` int unsigned DEFAULT NULL,
  `end_column` int unsigned DEFAULT NULL,
  `stable_alert_identifier` binary(21) NOT NULL,
  `suppressed` tinyint(1) NOT NULL DEFAULT '0',
  `message` varchar(4096) COLLATE utf8mb4_general_ci NOT NULL,
  `message_markdown` varchar(4096) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `severity_level` tinyint unsigned NOT NULL,
  `security_severity` double DEFAULT NULL,
  `analysis_id` bigint unsigned NOT NULL,
  `last_seen_analysis_id` bigint unsigned DEFAULT NULL,
  `code_flows_document_id` bigint unsigned DEFAULT NULL,
  `is_fixed` tinyint(1) GENERATED ALWAYS AS ((`last_seen_analysis_id` is not null)) VIRTUAL,
  `file_classification` json NOT NULL,
  `snippet_id` bigint unsigned DEFAULT NULL,
  `guid` varchar(36) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_physical_alerts_on_repo_id_analysis_id` (`repository_id`,`analysis_id`),
  KEY `idx_physical_alerts_on_repo_id_logical_alert_id` (`repository_id`,`logical_alert_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
